package com.hau.notification.infrastructure;import com.hau.notification.domain.model.*;import com.hau.notification.domain.repository.NotificationRepository;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.UUID;import static org.assertj.core.api.Assertions.*;@SpringBootTest@Transactional class PersistenceTest{@Autowired NotificationRepository repository;@Test void storesAndCountsUnread(){UUID user=UUID.randomUUID();repository.save(Notification.unread(user,NotificationType.SYSTEM,"Title","Content",null,null,Instant.now()));assertThat(repository.countUnread(user)).isEqualTo(1);assertThat(repository.markAllRead(user,Instant.now())).isEqualTo(1);}}
